CREATE TABLE IF NOT EXISTS `agent_account`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理人编码（渠道内唯一，与本渠道 agent_info 1:1）',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属渠道编码（账号的渠道归属，登录隔离维度）',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '登录用户名（渠道内唯一，手机号/微信/ext 账号登录时可空）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '登录手机号（不要求全局唯一）',
  `password` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '密码（加密存储；渠道外部账号登录时可空）',
  `salt` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '密码盐值',
  `open_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信OpenID（不要求全局唯一）',
  `union_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信UnionID（不要求全局唯一）',
  `ext_account_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '渠道本身账号系统的唯一编码；NULL=大雁自建账号',
  `account_status` tinyint NOT NULL DEFAULT 1 COMMENT '账号状态（0=锁定, 1=正常, 2=禁用）',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后登录IP',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_channel_username`(`channel_code` ASC, `username` ASC) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_open_id`(`open_id` ASC) USING BTREE,
  INDEX `idx_union_id`(`union_id` ASC) USING BTREE,
  INDEX `idx_ext_account_no`(`ext_account_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '代理人账号' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `agent_client_rel`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理人编码',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `bind_type` tinyint NOT NULL DEFAULT 1 COMMENT '绑定类型（1=权益赠送绑定, 2=活动邀请绑定, 3=自主绑定）',
  `bind_time` datetime NOT NULL COMMENT '绑定时间',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=已解绑, 1=服务中）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '代理人-客户绑定关系' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `agent_content`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `agent_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理人编码',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '摘要',
  `cover_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '封面（OSS key）',
  `content_type` tinyint NOT NULL COMMENT '形态（1=图文 2=朋友圈 3=视频脚本）',
  `content_body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '正文（图文=HTML；朋友圈=纯文本；脚本=结构化文本）',
  `style_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '风格档位（professional/warm/authoritative/colloquial）',
  `ref_content_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '参考范文 contentCode',
  `ref_kb_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '勾选知识库文档 JSON（[{fileId,fileName}]）',
  `ref_goods_codes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '勾选商品 codes JSON（[\"GDxxx\"]）',
  `audience` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标读者（children=子女决策者/elder=老人本人/general=通用）',
  `purpose` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文章目的（product/park/science）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（1=正常）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除（0=未删,1=已删）',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '代理人 AI 生成个人内容' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `agent_favorite`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理人编码',
  `target_type` tinyint NOT NULL COMMENT '收藏对象类型（1=养老机构, 2=场景, 3=课程, 4=内容）',
  `target_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收藏对象编码',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_agent_target`(`agent_code` ASC, `target_type` ASC, `target_code` ASC) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_target`(`target_type` ASC, `target_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '代理人收藏夹' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `agent_info`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理人编码（AG+5位数字，渠道内唯一）',
  `full_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理人姓名',
  `gender` tinyint(1) NOT NULL DEFAULT 0 COMMENT '性别（0=未知, 1=男, 2=女）',
  `avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像URL',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '手机号',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `id_card` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '身份证号（加密存储）',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属渠道编码',
  `company_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '保险公司名称',
  `branch_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分支机构',
  `department` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部门',
  `position` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '职位',
  `employee_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '保险公司工号',
  `license_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '从业资格证号',
  `province_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '省份编码',
  `city_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '城市编码',
  `district_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区划编码',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '详细地址',
  `service_intro` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '服务介绍',
  `client_count` int NOT NULL DEFAULT 0 COMMENT '服务客户数',
  `total_order_count` int NOT NULL DEFAULT 0 COMMENT '累计订单数',
  `total_order_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '累计订单金额',
  `agent_level` tinyint NOT NULL DEFAULT 1 COMMENT '等级（1=普通, 2=银牌, 3=金牌, 4=钻石）',
  `is_certified` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否认证（0=否, 1=是）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=正常, 2=冻结）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_channel_agent_code`(`channel_code` ASC, `agent_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_city_code`(`city_code` ASC) USING BTREE,
  INDEX `idx_agent_level`(`agent_level` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '代理人信息' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `agent_lead`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `lead_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索编码（LD+日期+序号，渠道内唯一）',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '归属代理人编码',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属渠道编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '线索姓名（可能只是称呼）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系电话',
  `gender` tinyint(1) NOT NULL DEFAULT 0 COMMENT '性别（0=未知, 1=男, 2=女）',
  `age` int NULL DEFAULT NULL COMMENT '年龄（可为空）',
  `lead_status` tinyint NOT NULL DEFAULT 1 COMMENT '线索状态（1=新线索, 2=跟进中, 3=意向, 4=已转化, 5=已流失）',
  `source_type` tinyint NOT NULL DEFAULT 1 COMMENT '来源类型（1=手工录入, 2=分享扫码, 3=活动接触, 4=转介绍, 5=内容引流）',
  `source_ref` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源溯源（share_code/activity_code/referrer 等）',
  `visitor_lead_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联访客线索编码（lead_info.lead_code；手工录入为 NULL）',
  `visitor_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '访客令牌（匿名唯一标识，UUID）',
  `visitor_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '访客来源（wechat/browser/unknown）',
  `wx_nickname` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信昵称',
  `wx_avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信头像URL',
  `last_trace_time` datetime NULL DEFAULT NULL COMMENT '最后互动时间',
  `trace_count` int NOT NULL DEFAULT 0 COMMENT '互动总次数',
  `intention_level` tinyint(1) NULL DEFAULT NULL COMMENT '意向等级（1=低, 2=中, 3=高）',
  `interest_type` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关注养老类型（旅居/活力长居/照护，逗号分隔）',
  `region` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关注区域',
  `last_follow_time` datetime NULL DEFAULT NULL COMMENT '最后跟进时间',
  `converted_client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '转化后的客户编码（关联 client_info.client_code）',
  `converted_at` datetime NULL DEFAULT NULL COMMENT '转化时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  `last_trace_type` int NULL DEFAULT NULL COMMENT '最后互动类型（1=内容 2=工具 3=海报）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_channel_lead_code`(`channel_code` ASC, `lead_code` ASC) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_lead_status`(`lead_status` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_source_type`(`source_type` ASC) USING BTREE,
  INDEX `idx_visitor_token`(`visitor_token` ASC) USING BTREE,
  INDEX `idx_last_trace_time`(`last_trace_time` ASC) USING BTREE,
  INDEX `idx_visitor_lead_code`(`visitor_lead_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '代理人线索' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `agent_performance`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理人编码',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属渠道编码',
  `period_type` tinyint NOT NULL COMMENT '统计周期（1=日, 2=周, 3=月, 4=季, 5=年）',
  `period_value` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '周期值',
  `equity_grant_count` int NOT NULL DEFAULT 0 COMMENT '权益赠送次数',
  `equity_grant_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '权益赠送金额',
  `scene_order_count` int NOT NULL DEFAULT 0 COMMENT '场景订单数',
  `scene_order_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '场景订单金额',
  `course_order_count` int NOT NULL DEFAULT 0 COMMENT '课程订单数',
  `course_order_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '课程订单金额',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_agent_period`(`agent_code` ASC, `period_type` ASC, `period_value` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '代理人业绩' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `agent_share_record`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `share_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分享编码',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '代理人编码',
  `share_type` tinyint NOT NULL COMMENT '分享类型（1=内容, 2=场景, 3=机构, 4=权益, 5=课程）',
  `biz_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分享对象编码',
  `share_channel` tinyint NULL DEFAULT NULL COMMENT '分享渠道（1=微信, 2=朋友圈, 3=复制链接, 4=二维码, 5=短信）',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '接收客户编码（已知客户时）',
  `view_count` int NOT NULL DEFAULT 0 COMMENT '浏览次数',
  `share_time` datetime NOT NULL COMMENT '分享时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_share_code`(`share_code` ASC) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_share_type`(`share_type` ASC) USING BTREE,
  INDEX `idx_share_time`(`share_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '代理人分享记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `butler_account`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `butler_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家编码',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '登录用户名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '手机号（支持手机号登录）',
  `password` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码（加密存储）',
  `salt` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '密码盐值',
  `open_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信OpenID（支持微信登录）',
  `union_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信UnionID（支持微信登录）',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `account_status` tinyint NOT NULL DEFAULT 1 COMMENT '账号状态（0=锁定, 1=正常, 2=禁用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_username`(`username` ASC) USING BTREE,
  INDEX `idx_butler_code`(`butler_code` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_open_id`(`open_id` ASC) USING BTREE,
  INDEX `idx_union_id`(`union_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '养老管家账号' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `butler_account_role_rel`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `account_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家账号编码',
  `butler_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家编码',
  `role_type` tinyint NOT NULL DEFAULT 1 COMMENT '角色类型（1=普通管家, 2=高级管家, 3=管家主管）',
  `description` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '角色描述',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_account_role`(`account_code` ASC, `role_type` ASC) USING BTREE,
  INDEX `idx_butler_code`(`butler_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管家账号角色关联' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `butler_client_rel`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `butler_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家编码',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `bind_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '绑定时间',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=已解绑, 1=服务中）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_butler_client`(`butler_code` ASC, `client_code` ASC, `status` ASC) USING BTREE,
  INDEX `idx_butler_code`(`butler_code` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管家-客户关系' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `butler_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `butler_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家编码（BL+5位数字）',
  `full_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家姓名',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '手机号',
  `avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像URL',
  `organ_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属组织编码',
  `account_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联后台账号编码（organ_account.account_code，未开通为 NULL）',
  `butler_level` tinyint NOT NULL DEFAULT 1 COMMENT '管家等级（1=初级, 2=中级, 3=高级, 4=金牌）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（0=离职, 1=在职）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_butler_code`(`butler_code` ASC) USING BTREE,
  INDEX `idx_organ_code`(`organ_code` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_account_code`(`account_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '养老管家信息' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `butler_rating`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `butler_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家编码',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `service_record_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联服务记录编码',
  `rating` tinyint(1) NOT NULL COMMENT '评分（1-5）',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '评价内容',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=已隐藏, 1=正常）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_butler_code`(`butler_code` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_rating`(`rating` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管家评价' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `butler_schedule`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `butler_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家编码',
  `schedule_date` date NOT NULL COMMENT '排班日期',
  `schedule_type` tinyint NOT NULL DEFAULT 1 COMMENT '排班类型（1=工作日, 2=休息日, 3=请假）',
  `start_time` time NULL DEFAULT NULL COMMENT '上班时间',
  `end_time` time NULL DEFAULT NULL COMMENT '下班时间',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=无效, 1=有效）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_butler_date`(`butler_code` ASC, `schedule_date` ASC) USING BTREE,
  INDEX `idx_schedule_date`(`schedule_date` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管家排班' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `butler_service_record`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `butler_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家编码',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `service_type` tinyint NOT NULL COMMENT '服务类型（1=需求评估, 2=方案定制, 3=全程安排, 4=回访品控）',
  `service_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '服务标题',
  `service_date` date NOT NULL COMMENT '服务日期',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=进行中, 1=已完成, 2=已取消）',
  `communicate_way` tinyint NULL DEFAULT NULL COMMENT '沟通方式（1=电话, 2=企业微信, 3=微信, 4=当面沟通, 5=其他）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_butler_code`(`butler_code` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_service_date`(`service_date` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管家服务记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `butler_skill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `butler_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管家编码',
  `skill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '技能编码（字典：butler_skill）',
  `skill_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '技能名称',
  `proficiency` tinyint NULL DEFAULT NULL COMMENT '熟练度（1=了解, 2=熟悉, 3=熟练, 4=精通）',
  `is_certified` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否持证（0=否, 1=是）',
  `certificate_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证书编号',
  `obtain_date` date NULL DEFAULT NULL COMMENT '取得日期',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_butler_skill`(`butler_code` ASC, `skill_code` ASC) USING BTREE,
  INDEX `idx_butler_code`(`butler_code` ASC) USING BTREE,
  INDEX `idx_skill_code`(`skill_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管家技能标签' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_account`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码',
  `account_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账号编码',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '登录用户名',
  `password` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码（加密存储）',
  `salt` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码盐值',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '真实姓名',
  `avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像URL',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '手机号',
  `open_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信OpenID（支持微信登录）',
  `union_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信UnionID（支持微信登录）',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `position` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '职位',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后登录IP',
  `login_count` int NOT NULL DEFAULT 0 COMMENT '累计登录次数',
  `account_status` tinyint NOT NULL DEFAULT 1 COMMENT '账号状态（0=锁定, 1=正常, 2=禁用）',
  `is_admin` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否管理员（0=否, 1=是）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_account_code`(`account_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_username`(`username` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_open_id`(`open_id` ASC) USING BTREE,
  INDEX `idx_union_id`(`union_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道账号' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_account_role_rel`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `account_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账号编码',
  `role_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色编码',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_account_role`(`account_code` ASC, `role_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道账号角色关联' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_config_content`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码',
  `content_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容编码',
  `content_type` tinyint NOT NULL COMMENT '内容类型（1=文章, 2=视频, 3=图片, 4=专题）',
  `app_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'agent' COMMENT '展示端类型（agent=代理人端, client=客户端）',
  `position` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '展示位置（banner/recommend/hot/new等）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `is_top` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否置顶（0=否, 1=是）',
  `effective_time` datetime NULL DEFAULT NULL COMMENT '生效时间',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '失效时间',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=启用）',
  `config_type` tinyint NOT NULL DEFAULT 0 COMMENT '配置类型（0=基础可见性，预留扩展）',
  `config_json` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '{}' COMMENT '配置内容 JSON（格式随 config_type 不同）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_content_code`(`content_code` ASC) USING BTREE,
  INDEX `idx_position`(`position` ASC) USING BTREE,
  INDEX `idx_sort_order`(`sort_order` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道内容配置' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_config_course`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '渠道编码',
  `course_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '课程编码（course_info.course_code）',
  `config_type` tinyint NOT NULL DEFAULT 0 COMMENT '配置类型（0=基础可见性，预留扩展）',
  `config_json` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '{}' COMMENT '配置内容 JSON（预留扩展）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（0=禁用 1=启用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `updater` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1=已删除，0=未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_channel_course_type`(`channel_code` ASC, `course_code` ASC, `config_type` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_course_code`(`course_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '渠道课程配置' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_config_goods`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码',
  `goods_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码',
  `goods_type` tinyint NOT NULL COMMENT '商品类型（1=养老权益, 2=场景营销, 3=培训课程, 4=旅游短居）',
  `custom_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '自定义商品名称',
  `custom_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '自定义价格',
  `custom_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '自定义描述',
  `is_exclusive` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否渠道专属（0=否, 1=是）',
  `purchase_limit` int NULL DEFAULT NULL COMMENT '采购限制数量（NULL=不限）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `effective_time` datetime NULL DEFAULT NULL COMMENT '生效时间',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '失效时间',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=启用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_goods_code`(`goods_code` ASC) USING BTREE,
  INDEX `idx_goods_type`(`goods_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道商品配置' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_config_scene`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码',
  `scene_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '场景编码',
  `is_exclusive` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否渠道专属（0=否, 1=是）',
  `custom_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '自定义场景名称（渠道定制）',
  `custom_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '自定义价格',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `effective_time` datetime NULL DEFAULT NULL COMMENT '生效时间',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '失效时间',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=启用）',
  `config_type` tinyint NOT NULL DEFAULT 0 COMMENT '配置类型（0=基础可见性，预留扩展）',
  `config_json` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '{}' COMMENT '配置内容 JSON（格式随 config_type 不同）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_scene_code`(`scene_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道场景配置' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_config_tool`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '渠道编码',
  `tool_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '工具编码（tool_info.tool_code，TL 前缀）',
  `config_type` tinyint NOT NULL COMMENT '配置类型（0=基础可见性，1=问答人物知识库补充）',
  `config_json` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '{}' COMMENT '配置内容 JSON（格式随 config_type 不同）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（0=禁用 1=启用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `updater` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1=已删除，0=未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_channel_tool_type`(`channel_code` ASC, `tool_code` ASC, `config_type` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_tool_code`(`tool_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '渠道工具配置' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码（CH+5位数字）',
  `full_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道名称',
  `short_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '简称',
  `channel_type` tinyint NOT NULL DEFAULT 1 COMMENT '渠道类型-企业类型（1=保险公司, 2=银行机构, 3=保险中介, 4=其他企业）',
  `parent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上级渠道编码（用于上下级关系）',
  `ancestors` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '祖级列表',
  `level` tinyint NOT NULL DEFAULT 1 COMMENT '层级（1=一级, 2=二级, 3=三级）',
  `unified_credit_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统一社会信用代码',
  `legal_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '法定代表人',
  `province_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '省份编码',
  `city_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '城市编码',
  `district_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区划编码',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '详细地址',
  `contact_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系电话',
  `contact_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系邮箱',
  `logo_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Logo URL',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '渠道介绍',
  `agent_count` int NOT NULL DEFAULT 0 COMMENT '旗下代理人数量',
  `total_order_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '累计订单金额',
  `cooperation_start_date` date NULL DEFAULT NULL COMMENT '合作开始日期',
  `distributor_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分销商编码（关联 distributor_info，无分销商时为空）',
  `settlement_cycle` tinyint NOT NULL DEFAULT 2 COMMENT '结算周期（1=月结, 2=季结）',
  `feature_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '渠道功能开关配置（JSON格式）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=待审核, 1=合作中, 2=已暂停, 3=已终止）',
  `audit_status` tinyint NOT NULL DEFAULT 0 COMMENT '审核状态（0=待审核, 1=审核通过, 2=审核驳回）',
  `can_manage` tinyint(1) NOT NULL DEFAULT 0 COMMENT '管理配置能力：0=业务型（仅采购/场景/数据/结算等业务），1=管理型（可建删子渠道+配置app）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_full_name`(`full_name`(50) ASC) USING BTREE,
  INDEX `idx_parent_code`(`parent_code` ASC) USING BTREE,
  INDEX `idx_channel_type`(`channel_type` ASC) USING BTREE,
  INDEX `idx_city_code`(`city_code` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_distributor_code`(`distributor_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道信息' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_open_platform`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码',
  `platform_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台名称',
  `dock_type` tinyint NOT NULL DEFAULT 1 COMMENT '对接类型（1=H5嵌入, 2=API对接, 3=SDK集成）',
  `api_base_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'API基础地址',
  `app_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用Key',
  `app_secret` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用密钥（加密存储）',
  `callback_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '回调地址',
  `h5_domain` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'H5域名配置',
  `h5_theme` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'H5主题配置',
  `auth_type` tinyint NOT NULL DEFAULT 1 COMMENT '认证方式（1=Token, 2=签名）',
  `ip_whitelist` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'IP白名单（JSON数组）',
  `rate_limit` int NULL DEFAULT 1000 COMMENT '调用频率限制（次/分钟）',
  `timeout` int NULL DEFAULT 30 COMMENT '超时时间（秒）',
  `extra_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '扩展配置（JSON格式）',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=启用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_app_key`(`app_key` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道开放平台' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_open_sync_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `sync_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '同步记录编码',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码',
  `sync_type` tinyint NOT NULL COMMENT '同步类型（1=内容推送, 2=场景推送, 3=权益同步, 4=订单回传, 5=客户回传）',
  `biz_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '业务编码（对应同步对象）',
  `direction` tinyint(1) NOT NULL DEFAULT 1 COMMENT '方向（1=推送至渠道, 2=渠道回调）',
  `request_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '请求报文（JSON）',
  `response_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '响应报文（JSON）',
  `http_status` int NULL DEFAULT NULL COMMENT 'HTTP状态码',
  `result` tinyint NULL DEFAULT NULL COMMENT '结果（0=失败, 1=成功）',
  `error_msg` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '错误信息',
  `retry_count` int NOT NULL DEFAULT 0 COMMENT '重试次数',
  `sync_time` datetime NOT NULL COMMENT '同步时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sync_code`(`sync_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_sync_type`(`sync_type` ASC) USING BTREE,
  INDEX `idx_result`(`result` ASC) USING BTREE,
  INDEX `idx_sync_time`(`sync_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道开放平台同步记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_permission`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `permission_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权限编码',
  `permission_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权限名称',
  `parent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '父权限编码（NULL=顶级）',
  `permission_type` tinyint NOT NULL COMMENT '权限类型（1=菜单, 2=按钮, 3=接口, 4=数据）',
  `path` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '路由/接口路径',
  `method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '请求方法',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=启用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_permission_code`(`permission_code` ASC) USING BTREE,
  INDEX `idx_parent_code`(`parent_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 150 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道权限' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_role`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属渠道编码',
  `role_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色编码',
  `role_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色名称',
  `role_type` tinyint NOT NULL DEFAULT 1 COMMENT '角色类型（1=系统预置, 2=自定义）',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '角色描述',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=启用）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_role_code`(`role_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道角色' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `channel_role_permission_ship`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色编码',
  `permission_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权限编码',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_role_permission`(`role_code` ASC, `permission_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '渠道角色权限关联' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `client_account`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码（渠道内唯一，与本渠道 client_info 1:1）',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属渠道编码（登录隔离维度）',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '登录用户名（渠道内唯一）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '登录手机号（不要求全局唯一）',
  `password` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '密码（BCrypt 加密存储）',
  `salt` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '密码盐值',
  `open_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信OpenID（不要求全局唯一）',
  `union_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信UnionID',
  `alipay_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '支付宝账号ID',
  `ext_account_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '渠道本身账号系统唯一编码（NULL=大雁自建账号）',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后登录IP',
  `login_count` int NOT NULL DEFAULT 0 COMMENT '累计登录次数',
  `account_status` tinyint NOT NULL DEFAULT 1 COMMENT '账号状态（0=锁定, 1=正常, 2=禁用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_channel_username`(`channel_code` ASC, `username` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_open_id`(`open_id` ASC) USING BTREE,
  INDEX `idx_union_id`(`union_id` ASC) USING BTREE,
  INDEX `idx_ext_account_no`(`ext_account_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户账号' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `client_address`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `receiver_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收货人姓名',
  `receiver_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收货人电话',
  `province_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '省编码',
  `city_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '城市编码',
  `district_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区编码',
  `detail_address` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '详细地址',
  `full_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '完整地址（省市区+详细）',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认地址（0=否, 1=是）',
  `tag` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '地址标签（家/公司等）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_is_default`(`is_default` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户收货地址' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `client_care_need`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `butler_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '评估管家编码',
  `butler_full_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '评估管家姓名（快照）',
  `eval_date` date NOT NULL COMMENT '评估日期',
  `care_level` tinyint NULL DEFAULT NULL COMMENT '建议照护等级（1=特级, 2=一级, 3=二级, 4=三级, 5=自理）',
  `care_type_preference` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '偏好照护类型（JSON数组）',
  `living_preference` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '居住偏好（JSON数组）',
  `food_preference` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '饮食偏好',
  `budget_min` decimal(12, 2) NULL DEFAULT NULL COMMENT '预算下限（元/月）',
  `budget_max` decimal(12, 2) NULL DEFAULT NULL COMMENT '预算上限（元/月）',
  `area_preference` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区域偏好（JSON数组）',
  `special_requirements` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '特殊需求说明',
  `expected_checkin_date` date NULL DEFAULT NULL COMMENT '期望入住日期',
  `park_recommendations` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '推荐机构列表（JSON数组）',
  `eval_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '评估结论',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=评估中, 1=已完成, 2=已过期）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_butler_code`(`butler_code` ASC) USING BTREE,
  INDEX `idx_eval_date`(`eval_date` ASC) USING BTREE,
  INDEX `idx_care_level`(`care_level` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户照护需求评估' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `client_family_member`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `member_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '成员姓名',
  `relation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '与客户关系（子女/配偶/兄弟姐妹等）',
  `gender` tinyint(1) NULL DEFAULT 0 COMMENT '性别（0=未知, 1=男, 2=女）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系电话',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `is_emergency_contact` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否紧急联系人（0=否, 1=是）',
  `is_primary_contact` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否主要联系人（0=否, 1=是）',
  `is_decision_maker` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否决策人（0=否, 1=是）',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '地址',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=启用）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_is_emergency_contact`(`is_emergency_contact` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户家庭成员/紧急联系人' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `client_favorite`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `target_type` tinyint NOT NULL COMMENT '收藏对象类型（1=养老机构, 2=场景, 3=课程, 4=内容）',
  `target_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收藏对象编码',
  `target_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收藏对象名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_client_target`(`client_code` ASC, `target_type` ASC, `target_code` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户收藏夹' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `client_health_profile`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `height` decimal(5, 1) NULL DEFAULT NULL COMMENT '身高（cm）',
  `weight` decimal(5, 1) NULL DEFAULT NULL COMMENT '体重（kg）',
  `blood_type` tinyint NULL DEFAULT NULL COMMENT '血型（1=A, 2=B, 3=AB, 4=O）',
  `blood_pressure` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '血压（如120/80）',
  `blood_sugar` decimal(5, 2) NULL DEFAULT NULL COMMENT '血糖（mmol/L）',
  `heart_rate` int NULL DEFAULT NULL COMMENT '心率（次/分）',
  `chronic_diseases` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '慢性病列表（JSON数组）',
  `allergy_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '过敏史',
  `surgery_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '手术史',
  `family_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '家族病史',
  `medication_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '当前用药信息',
  `mobility_level` tinyint NULL DEFAULT NULL COMMENT '行动能力（1=完全自理, 2=部分自理, 3=需要协助, 4=完全依赖）',
  `cognitive_level` tinyint NULL DEFAULT NULL COMMENT '认知能力（1=正常, 2=轻度障碍, 3=中度障碍, 4=重度障碍）',
  `mental_status` tinyint NULL DEFAULT NULL COMMENT '心理状态（1=良好, 2=一般, 3=需关注）',
  `diet_preference` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '饮食偏好（JSON数组）',
  `sleep_quality` tinyint NULL DEFAULT NULL COMMENT '睡眠质量（1=良好, 2=一般, 3=较差）',
  `emergency_contact_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '紧急联系人姓名',
  `emergency_contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '紧急联系人电话',
  `emergency_contact_relation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '紧急联系人关系',
  `health_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '健康评分',
  `last_assessment_time` datetime NULL DEFAULT NULL COMMENT '最近评估时间',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_mobility_level`(`mobility_level` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户健康档案' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `client_info`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码（CL+5位数字，渠道内唯一）',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属渠道编码（按渠道隔离）',
  `full_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户姓名',
  `gender` tinyint(1) NOT NULL DEFAULT 0 COMMENT '性别（0=未知, 1=男, 2=女）',
  `avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像URL',
  `birthday` date NULL DEFAULT NULL COMMENT '出生日期',
  `age` tinyint NULL DEFAULT NULL COMMENT '年龄（冗余，定期更新）',
  `id_card` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '身份证号（加密存储）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '手机号',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `province_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '省份编码',
  `city_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '城市编码',
  `district_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区划编码',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '详细地址',
  `nationality` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '国籍',
  `ethnic` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '民族',
  `education` tinyint NULL DEFAULT NULL COMMENT '学历',
  `marital_status` tinyint NULL DEFAULT NULL COMMENT '婚姻状况（1=未婚, 2=已婚, 3=离异, 4=丧偶）',
  `profession` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '职业',
  `source_type` tinyint NOT NULL DEFAULT 1 COMMENT '来源渠道（1=自主注册, 2=代理人邀请, 3=权益激活, 4=管家录入）',
  `source_agent_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源代理人编码',
  `source_channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源渠道编码',
  `client_level` tinyint NOT NULL DEFAULT 1 COMMENT '客户等级（1=普通, 2=VIP, 3=SVIP）',
  `equity_count` int NOT NULL DEFAULT 0 COMMENT '持有权益数',
  `used_equity_count` int NOT NULL DEFAULT 0 COMMENT '已使用权益数',
  `service_count` int NOT NULL DEFAULT 0 COMMENT '累计服务次数',
  `total_order_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '累计消费金额',
  `last_service_time` datetime NULL DEFAULT NULL COMMENT '最近服务时间',
  `register_time` datetime NULL DEFAULT NULL COMMENT '注册时间',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `is_vip` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否VIP（0=否, 1=是）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=正常, 2=冻结）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_channel_client_code`(`channel_code` ASC, `client_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_id_card`(`id_card` ASC) USING BTREE,
  INDEX `idx_city_code`(`city_code` ASC) USING BTREE,
  INDEX `idx_source_type`(`source_type` ASC) USING BTREE,
  INDEX `idx_source_agent_code`(`source_agent_code` ASC) USING BTREE,
  INDEX `idx_client_level`(`client_level` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户信息' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `content_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `content_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容编码',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `subtitle` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '副标题',
  `content_type` tinyint NOT NULL COMMENT '内容类型（1=文章, 2=视频, 3=图片集, 4=专题, 5=问答）',
  `category_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类编码',
  `author_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '作者姓名',
  `author_avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '作者头像',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '封面图URL',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '摘要',
  `content_body` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '正文内容（富文本HTML）',
  `source_type` tinyint NOT NULL DEFAULT 1 COMMENT '来源类型（1=原创, 2=转载, 3=采编）',
  `source_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源链接',
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标签（JSON数组）',
  `network_tags` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '适用业态（逗号分隔: vital/care/sojourn），空=全部',
  `is_top` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否置顶（0=否, 1=是）',
  `is_recommend` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否推荐（0=否, 1=是）',
  `is_comment` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否允许评论（0=否, 1=是）',
  `view_count` int NOT NULL DEFAULT 0 COMMENT '浏览次数',
  `like_count` int NOT NULL DEFAULT 0 COMMENT '点赞次数',
  `comment_count` int NOT NULL DEFAULT 0 COMMENT '评论次数',
  `share_count` int NOT NULL DEFAULT 0 COMMENT '分享次数',
  `collect_count` int NOT NULL DEFAULT 0 COMMENT '收藏次数',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `content_status` tinyint NOT NULL DEFAULT 0 COMMENT '内容状态（0=草稿, 1=待审核, 2=审核通过, 3=审核驳回, 4=已下线）',
  `audit_status` tinyint NOT NULL DEFAULT 0 COMMENT '审核状态（0=未审核, 2=通过, 3=驳回）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_content_code`(`content_code` ASC) USING BTREE,
  INDEX `idx_content_type`(`content_type` ASC) USING BTREE,
  INDEX `idx_category_code`(`category_code` ASC) USING BTREE,
  INDEX `idx_publish_time`(`publish_time` ASC) USING BTREE,
  INDEX `idx_content_status`(`content_status` ASC) USING BTREE,
  INDEX `idx_is_top`(`is_top` ASC) USING BTREE,
  INDEX `idx_sort_order`(`sort_order` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '内容信息' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `content_media`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `content_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容编码',
  `media_type` tinyint NOT NULL COMMENT '媒体类型（1=图片, 2=视频, 3=音频, 4=附件）',
  `media_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源URL',
  `thumbnail_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '缩略图URL',
  `media_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源名称',
  `file_format` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件格式',
  `file_size` int NULL DEFAULT NULL COMMENT '文件大小（KB）',
  `width` int NULL DEFAULT NULL COMMENT '宽度（像素）',
  `height` int NULL DEFAULT NULL COMMENT '高度（像素）',
  `duration` int NULL DEFAULT NULL COMMENT '时长（秒，视频/音频）',
  `media_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源描述',
  `is_in_body` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否在正文中（0=否, 1=是）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_content_code`(`content_code` ASC) USING BTREE,
  INDEX `idx_media_type`(`media_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '内容多媒体资源' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `content_record_read`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `content_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容编码',
  `reader_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '阅读者类型（agent/client/butler/guest）',
  `reader_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '阅读者编码',
  `read_duration` int NULL DEFAULT NULL COMMENT '阅读时长（秒）',
  `read_progress` decimal(5, 2) NULL DEFAULT NULL COMMENT '阅读进度（%）',
  `read_source` tinyint NOT NULL DEFAULT 1 COMMENT '阅读来源（1=自主浏览, 2=分享链接, 3=推荐, 4=搜索）',
  `ip_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'IP地址',
  `device_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备类型',
  `read_time` datetime NOT NULL COMMENT '阅读时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_content_code`(`content_code` ASC) USING BTREE,
  INDEX `idx_reader`(`reader_type` ASC, `reader_code` ASC) USING BTREE,
  INDEX `idx_read_time`(`read_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '内容阅读记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `content_record_share`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `content_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容编码',
  `sharer_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分享者类型（agent/client/butler）',
  `sharer_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分享者编码',
  `share_channel` tinyint NOT NULL COMMENT '分享渠道（1=微信, 2=朋友圈, 3=QQ, 4=微博, 5=复制链接, 99=其它）',
  `share_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分享链接',
  `share_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分享标题',
  `share_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分享描述',
  `share_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分享缩略图',
  `click_count` int NOT NULL DEFAULT 0 COMMENT '点击次数',
  `convert_count` int NOT NULL DEFAULT 0 COMMENT '转化次数',
  `share_time` datetime NOT NULL COMMENT '分享时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_content_code`(`content_code` ASC) USING BTREE,
  INDEX `idx_sharer`(`sharer_type` ASC, `sharer_code` ASC) USING BTREE,
  INDEX `idx_share_time`(`share_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '内容分享记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `course_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `course_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程编码',
  `course_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程名称',
  `course_type` tinyint NULL DEFAULT NULL COMMENT '课程类型（1=线上录播, 2=线上直播, 3=线下课程, 4=混合课程；非平台自研板块可空）',
  `course_source` tinyint NOT NULL DEFAULT 1 COMMENT '板块来源（1=平台自研大雁 2=渠道课程 3=外部课程 4=雁鸣中国资讯）',
  `category_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类编码',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '封面图URL',
  `video_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '宣传视频URL',
  `course_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '课程描述',
  `course_body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '正文（详情页长文，纯文本）',
  `badge` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '角标（热/新/要闻/人物/动态/洞察）',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间（资讯/内容用，课程走开课日期）',
  `course_outline` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '课程大纲（JSON格式）',
  `target_audience` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标人群',
  `learning_objectives` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学习目标',
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '作者/来源（渠道/外部/资讯用，平台课程走讲师）',
  `duration_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '时长展示文本（如 28:30 / 约 15 分钟）',
  `lecturer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主讲讲师编码',
  `total_class` int NOT NULL DEFAULT 0 COMMENT '总课时数',
  `total_duration` int NULL DEFAULT NULL COMMENT '总时长（分钟）',
  `valid_days` int NULL DEFAULT NULL COMMENT '有效天数',
  `original_price` decimal(12, 2) NOT NULL COMMENT '原价',
  `sale_price` decimal(12, 2) NOT NULL COMMENT '售价',
  `max_students` int NULL DEFAULT NULL COMMENT '最大学员数（线下/直播课）',
  `current_students` int NOT NULL DEFAULT 0 COMMENT '当前学员数',
  `view_count` int NOT NULL DEFAULT 0 COMMENT '浏览次数',
  `sales_count` int NOT NULL DEFAULT 0 COMMENT '已售数量',
  `rating_avg` decimal(3, 2) NULL DEFAULT NULL COMMENT '平均评分',
  `is_free` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否免费（0=否, 1=是）',
  `is_recommend` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否推荐',
  `course_start_date` date NULL DEFAULT NULL COMMENT '开课日期',
  `course_end_date` date NULL DEFAULT NULL COMMENT '结课日期',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `course_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=草稿, 1=待上架, 2=已上架, 3=已下架, 4=已结课）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '渠道编码（渠道课程标识归属，平台课程为 NULL）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_course_code`(`course_code` ASC) USING BTREE,
  INDEX `idx_course_type`(`course_type` ASC) USING BTREE,
  INDEX `idx_lecturer_code`(`lecturer_code` ASC) USING BTREE,
  INDEX `idx_course_status`(`course_status` ASC) USING BTREE,
  INDEX `idx_sort_order`(`sort_order` ASC) USING BTREE,
  INDEX `idx_course_source`(`course_source` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1000025 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程信息（学习中心四板块：大雁/渠道/外部/雁鸣中国，course_source 区隔）' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `course_lecturer`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `lecturer_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '讲师编码',
  `lecturer_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '讲师姓名',
  `gender` tinyint(1) NULL DEFAULT 0 COMMENT '性别（0=未知, 1=男, 2=女）',
  `avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像URL',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '职称/头衔',
  `organization` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '所属机构',
  `specialty` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '擅长领域（JSON数组）',
  `introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '讲师简介',
  `certifications` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '资质证书（JSON数组）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系电话',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系邮箱',
  `course_count` int NOT NULL DEFAULT 0 COMMENT '开课数量',
  `student_count` int NOT NULL DEFAULT 0 COMMENT '学员总数',
  `rating_avg` decimal(3, 2) NULL DEFAULT NULL COMMENT '平均评分',
  `is_certified` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否平台认证（0=否, 1=是）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（0=禁用, 1=启用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_lecturer_code`(`lecturer_code` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程讲师' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `course_record_learn`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `course_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程编码',
  `client_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '学员客户编码',
  `agent_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '学员代理人编码',
  `learner_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学员姓名',
  `learner_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '学员手机号',
  `enroll_time` datetime NOT NULL COMMENT '报名时间',
  `order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联订单编码',
  `current_lesson` int NOT NULL DEFAULT 0 COMMENT '当前学到第几课',
  `total_lesson` int NOT NULL DEFAULT 0 COMMENT '总课时',
  `learn_progress` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '学习进度（%）',
  `total_learn_time` int NOT NULL DEFAULT 0 COMMENT '累计学习时长（分钟）',
  `last_learn_time` datetime NULL DEFAULT NULL COMMENT '最近学习时间',
  `is_completed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否完成（0=否, 1=是）',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `certificate_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '结业证书URL',
  `rating` tinyint(1) NULL DEFAULT NULL COMMENT '课程评分（1-5）',
  `rating_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '评价内容',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（0=已退课, 1=学习中, 2=已完成, 3=已过期）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_course_code`(`course_code` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_is_completed`(`is_completed` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程学习记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `distributor_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `distributor_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分销商编码（DS+5位数字）',
  `full_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分销商全称（企业全称或个人姓名）',
  `short_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '简称',
  `subject_type` tinyint NOT NULL DEFAULT 1 COMMENT '主体类型（1=企业, 2=个人）',
  `unified_credit_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统一社会信用代码（企业）',
  `legal_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '法定代表人（企业）',
  `business_license_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '营业执照号（企业）',
  `registered_capital` decimal(12, 2) NULL DEFAULT NULL COMMENT '注册资本（企业）',
  `establish_date` date NULL DEFAULT NULL COMMENT '成立日期（企业）',
  `id_card` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '身份证号（个人；预留 AES-256-GCM 密文宽度，密文为 Base64(IV||ciphertext||tag)）',
  `gender` tinyint(1) NULL DEFAULT 0 COMMENT '性别（个人，0=未知, 1=男, 2=女）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系电话',
  `contact_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系人',
  `contact_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系邮箱',
  `province_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '省份编码',
  `city_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '城市编码',
  `district_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区划编码',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '详细地址',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '银行账号（预留 AES-256-GCM 密文宽度，密文为 Base64(IV||ciphertext||tag)）',
  `bank_account_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '银行户名',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=待审核, 1=已合作, 2=已暂停, 3=已终止）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_distributor_code`(`distributor_code` ASC) USING BTREE,
  INDEX `idx_subject_type`(`subject_type` ASC) USING BTREE,
  INDEX `idx_unified_credit_code`(`unified_credit_code` ASC) USING BTREE,
  INDEX `idx_city_code`(`city_code` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '分销商信息' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `equity_activate`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `activate_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '激活记录编码',
  `equity_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益编码',
  `goods_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '激活客户编码',
  `client_full_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '激活客户姓名（快照）',
  `client_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `activate_channel` tinyint NOT NULL DEFAULT 1 COMMENT '激活渠道（1=APP, 2=小程序, 3=H5, 4=管家代激活, 5=代理人代激活）',
  `activate_source_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '激活来源编码（如代理人编码）',
  `activate_time` datetime NOT NULL COMMENT '激活时间',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '过期时间（终身权益为NULL）',
  `is_id_card_verified` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否实名认证（0=否, 1=是）',
  `is_agreement_signed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否签署协议（0=否, 1=是）',
  `ip_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '激活IP',
  `device_info` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备信息',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_activate_code`(`activate_code` ASC) USING BTREE,
  INDEX `idx_equity_code`(`equity_code` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_activate_time`(`activate_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '权益激活记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `equity_batch`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `batch_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批次编码',
  `batch_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批次名称',
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码（关联 goods_info.goods_code）',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分配渠道编码（NULL=未分配）',
  `total_quantity` int NOT NULL COMMENT '总数量',
  `produced_count` int NOT NULL DEFAULT 0 COMMENT '已生成数量',
  `allocated_count` int NOT NULL DEFAULT 0 COMMENT '已分配数量',
  `outbound_count` int NOT NULL DEFAULT 0 COMMENT '已出库数量',
  `activated_count` int NOT NULL DEFAULT 0 COMMENT '已激活数量',
  `used_count` int NOT NULL DEFAULT 0 COMMENT '已使用数量',
  `expired_count` int NOT NULL DEFAULT 0 COMMENT '已过期数量',
  `voided_count` int NOT NULL DEFAULT 0 COMMENT '已作废数量',
  `remain_count` int NOT NULL DEFAULT 0 COMMENT '剩余可用数量',
  `unit_cost` decimal(12, 2) NOT NULL COMMENT '单位成本',
  `total_cost` decimal(14, 2) NOT NULL COMMENT '批次总成本',
  `produce_date` date NOT NULL COMMENT '生产日期',
  `expire_date` date NOT NULL COMMENT '批次有效期',
  `batch_status` tinyint NOT NULL DEFAULT 0 COMMENT '批次状态（0=待生产, 1=生产中, 2=已完成, 3=已出库, 4=已关闭）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_batch_code`(`batch_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_batch_status`(`batch_status` ASC) USING BTREE,
  INDEX `idx_expire_date`(`expire_date` ASC) USING BTREE,
  INDEX `idx_goods_code`(`goods_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '权益批次管理' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `equity_change_holder`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `equity_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益编码',
  `old_use_person_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原权益使用人编码',
  `old_person_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原权益人姓名',
  `old_person_id_card` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原权益人身份证号（加密存储）',
  `new_use_person_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '新权益使用人编码',
  `new_person_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '新权益人姓名',
  `new_person_id_card` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '新权益人身份证号（加密存储）',
  `change_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更换原因',
  `change_status` tinyint NOT NULL DEFAULT 0 COMMENT '更换状态（0=待处理, 1=已完成, 2=已回滚）',
  `operate_time` datetime NOT NULL COMMENT '操作时间',
  `operator_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '操作人编码',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_equity_code`(`equity_code` ASC) USING BTREE,
  INDEX `idx_change_status`(`change_status` ASC) USING BTREE,
  INDEX `idx_operate_time`(`operate_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '更换权益人记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `equity_depot`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `equity_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益编码（EQ+12位数字）',
  `equity_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益卡号（对外展示用）',
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码（入库时从批次快照）',
  `person_count` int NOT NULL DEFAULT 1 COMMENT '使用人人数快照（入库时从 goods_equity 冻结）',
  `validity_type` tinyint(1) NULL DEFAULT NULL COMMENT '权益期限类型快照（1=固定天数,2=终身；入库时从goods_equity冻结）',
  `holder_rule` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '权益人构成规则快照（入库时从goods_equity冻结，激活建人按此校验）',
  `share_mode` tinyint(1) NULL DEFAULT NULL COMMENT '配额归属快照（0=按人独立,1=共享池；入库时从goods_equity冻结）',
  `valid_days` int NOT NULL DEFAULT 365 COMMENT '激活后有效天数快照（入库时从 goods_equity 冻结）',
  `batch_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批次编码',
  `cost_price` decimal(12, 2) NOT NULL COMMENT '成本价',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分配渠道编码',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分配代理人编码',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '领取客户编码',
  `produce_time` datetime NOT NULL COMMENT '入库时间',
  `allocate_time` datetime NULL DEFAULT NULL COMMENT '分配时间',
  `outbound_channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '出库寄送渠道编码（出库时填写，记录寄送给哪个渠道）',
  `outbound_agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '出库寄送代理人编码（出库时填写，记录寄送给哪个代理人）',
  `outbound_time` datetime NULL DEFAULT NULL COMMENT '出库时间',
  `logistics_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物流单号（出库寄送物流追踪号）',
  `activate_time` datetime NULL DEFAULT NULL COMMENT '激活时间',
  `first_use_time` datetime NULL DEFAULT NULL COMMENT '首次使用时间',
  `last_use_time` datetime NULL DEFAULT NULL COMMENT '最近使用时间',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '过期时间（激活后计算）',
  `shelf_expire_time` datetime NOT NULL COMMENT '库存过期时间（未激活有效期）',
  `card_secret` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '卡密（加密存储，激活验证用）',
  `carrier_type` tinyint NOT NULL DEFAULT 1 COMMENT '载体类型（1=权益卡, 2=权益函）',
  `activate_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '激活码（DY-8位，权益卡专用）',
  `bind_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '绑定码（BF-12位，权益函专用）',
  `qr_code_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '权益二维码URL',
  `order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联订单编码',
  `equity_status` tinyint NOT NULL DEFAULT 0 COMMENT '权益状态（0=库存中, 1=已出库, 2=已激活, 3=使用中, 4=已完成, 5=已过期, 6=已作废, 7=更换权益人中）',
  `void_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '作废原因',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_equity_code`(`equity_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_equity_no`(`equity_no` ASC) USING BTREE,
  INDEX `idx_batch_code`(`batch_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_equity_status`(`equity_status` ASC) USING BTREE,
  INDEX `idx_expire_time`(`expire_time` ASC) USING BTREE,
  INDEX `idx_order_code`(`order_code` ASC) USING BTREE,
  INDEX `idx_carrier_type`(`carrier_type` ASC) USING BTREE,
  INDEX `idx_goods_code`(`goods_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '权益卡/函库' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `equity_use_person`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `equity_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益编码',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益持有人编码（激活权益的客户）',
  `use_person_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '使用人姓名',
  `use_person_gender` tinyint(1) NULL DEFAULT 0 COMMENT '使用人性别（0=未知, 1=男, 2=女）',
  `use_person_birthday` date NULL DEFAULT NULL COMMENT '使用人出生日期',
  `use_person_age` tinyint NULL DEFAULT NULL COMMENT '使用人年龄',
  `use_person_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '使用人手机号',
  `use_person_id_card` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '使用人身份证号（AES-256-GCM 密文，Base64(IV||ciphertext||tag)）',
  `relation_with_holder` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '与持有人关系（本人/配偶/子女/父母/其他）',
  `health_status` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '健康状况简述',
  `care_need` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '照护需求简述',
  `is_default_holder` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否默认权益人（0=否, 1=是；一张权益仅一人为默认权益人，可被 equity_change_holder 更换）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_equity_code`(`equity_code` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE,
  INDEX `idx_is_default_holder`(`is_default_holder` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '权益使用人' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `finance_account`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `account_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账目编码',
  `direction` tinyint NOT NULL COMMENT '账目方向（1=应收, 2=应付）',
  `account_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象类型（channel/supplier/agent）',
  `target_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象编码',
  `target_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象名称',
  `biz_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型（字符串枚举：equity_purchase=权益采购, scene_fee=场景费用, service_fee=服务费）',
  `biz_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '业务编码',
  `total_amount` decimal(14, 2) NOT NULL COMMENT '应收/应付总额',
  `received_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '已收/已付金额',
  `remain_amount` decimal(14, 2) NOT NULL COMMENT '未收/未付金额',
  `due_date` date NULL DEFAULT NULL COMMENT '到期日期',
  `last_receive_time` datetime NULL DEFAULT NULL COMMENT '最近收款/付款时间',
  `account_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=待收/付, 1=部分收/付, 2=已结清, 3=已逾期, 4=已坏账）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_account_code`(`account_code` ASC) USING BTREE,
  INDEX `idx_direction`(`direction` ASC) USING BTREE,
  INDEX `idx_account`(`account_type` ASC, `target_code` ASC) USING BTREE,
  INDEX `idx_due_date`(`due_date` ASC) USING BTREE,
  INDEX `idx_account_status`(`account_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '应收应付账目' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `finance_bill`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结算单编号',
  `bill_type` tinyint NOT NULL COMMENT '结算类型（1=渠道结算, 2=供应商结算）',
  `target_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结算对象类型（channel/supplier/distributor）',
  `target_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结算对象编码',
  `target_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结算对象名称',
  `period_start` date NOT NULL COMMENT '结算周期开始',
  `period_end` date NOT NULL COMMENT '结算周期结束',
  `order_count` int NOT NULL DEFAULT 0 COMMENT '订单数量',
  `total_amount` decimal(14, 2) NOT NULL COMMENT '结算总额',
  `commission_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '分销手续费金额',
  `refund_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `adjust_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '调整金额',
  `final_amount` decimal(14, 2) NOT NULL COMMENT '最终结算金额',
  `flow_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '关联流水ID列表（JSON数组）',
  `settlement_method` tinyint NOT NULL DEFAULT 1 COMMENT '结算方式（1=银行转账, 2=线上转账）',
  `bank_info` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收款银行信息',
  `apply_time` datetime NULL DEFAULT NULL COMMENT '申请时间',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '结算完成时间',
  `auditor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核人编码',
  `auditor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核人姓名',
  `audit_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核备注',
  `bill_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=待审核, 1=审核通过, 2=结算中, 3=已结算, 4=审核拒绝）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_code`(`bill_code` ASC) USING BTREE,
  INDEX `idx_bill_type`(`bill_type` ASC) USING BTREE,
  INDEX `idx_target`(`target_type` ASC, `target_code` ASC) USING BTREE,
  INDEX `idx_period`(`period_start` ASC, `period_end` ASC) USING BTREE,
  INDEX `idx_bill_status`(`bill_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '结算单' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `finance_flow`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `flow_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流水编号',
  `flow_type` tinyint NOT NULL COMMENT '流水类型（1=收入, 2=支出, 3=退款, 4=结算）',
  `biz_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型（字符串枚举：equity_order=权益订单, scene_order=场景订单, course_order=课程订单, travel_order=旅居订单, settlement=结算）',
  `biz_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '业务编码',
  `account_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账号类型（organ/channel/agent/client/supplier）',
  `account_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账号编码',
  `flow_amount` decimal(14, 2) NOT NULL COMMENT '流水金额',
  `balance_before` decimal(14, 2) NOT NULL COMMENT '变动前余额',
  `balance_after` decimal(14, 2) NOT NULL COMMENT '变动后余额',
  `pay_type` tinyint NULL DEFAULT NULL COMMENT '支付方式（pay_type 字典：1=微信支付, 2=支付宝, 3=银行转账, 4=余额支付, 5=线下支付）',
  `trade_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '交易流水号',
  `counterparty_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对方类型',
  `counterparty_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对方编码',
  `counterparty_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对方名称',
  `flow_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流水描述',
  `flow_time` datetime NOT NULL COMMENT '流水时间',
  `is_settled` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已结算（0=否, 1=是）',
  `settle_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '结算单编码',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（0=已冲正, 1=正常）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_flow_code`(`flow_code` ASC) USING BTREE,
  INDEX `idx_flow_type`(`flow_type` ASC) USING BTREE,
  INDEX `idx_biz`(`biz_type` ASC, `biz_code` ASC) USING BTREE,
  INDEX `idx_account`(`account_type` ASC, `account_code` ASC) USING BTREE,
  INDEX `idx_flow_time`(`flow_time` ASC) USING BTREE,
  INDEX `idx_is_settled`(`is_settled` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '财务流水' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `finance_invoice`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `invoice_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票编码',
  `invoice_type` tinyint NOT NULL COMMENT '发票类型（1=增值税普通发票, 2=增值税专用发票, 3=电子发票）',
  `bill_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联结算单编码',
  `order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联订单编码',
  `applicant_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '申请方类型（channel/agent/client）',
  `applicant_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '申请方编码',
  `applicant_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '申请方名称',
  `title_type` tinyint NOT NULL DEFAULT 1 COMMENT '抬头类型（1=企业, 2=个人）',
  `invoice_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票抬头',
  `tax_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '纳税人识别号',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '银行账号',
  `register_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '注册地址',
  `register_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '注册电话',
  `invoice_amount` decimal(14, 2) NOT NULL COMMENT '开票金额',
  `invoice_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票内容',
  `receiver_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收件人姓名',
  `receiver_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收件人电话',
  `receiver_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收件地址',
  `receiver_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收件邮箱（电子发票）',
  `invoice_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票号码',
  `invoice_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票文件URL',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `issue_time` datetime NULL DEFAULT NULL COMMENT '开票时间',
  `send_time` datetime NULL DEFAULT NULL COMMENT '寄出时间',
  `invoice_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=待审核, 1=已审核, 2=已开票, 3=已寄出, 4=已完成, 5=已作废, 6=已红冲）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_invoice_code`(`invoice_code` ASC) USING BTREE,
  INDEX `idx_bill_code`(`bill_code` ASC) USING BTREE,
  INDEX `idx_applicant`(`applicant_type` ASC, `applicant_code` ASC) USING BTREE,
  INDEX `idx_invoice_no`(`invoice_no` ASC) USING BTREE,
  INDEX `idx_invoice_status`(`invoice_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '发票' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `finance_payment`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `payment_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '支付流水号',
  `order_type` tinyint NOT NULL COMMENT '订单类型（1=权益, 2=场景, 3=课程, 4=旅居）',
  `order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单编号',
  `pay_type` tinyint NOT NULL COMMENT '支付方式（pay_type 字典：1=微信支付, 2=支付宝, 3=银行转账, 4=余额支付, 5=线下支付）',
  `pay_amount` decimal(14, 2) NOT NULL COMMENT '支付金额',
  `trade_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '第三方交易号',
  `payer_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '付款方账号',
  `payee_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收款方账号',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `notify_time` datetime NULL DEFAULT NULL COMMENT '回调通知时间',
  `pay_status` tinyint NOT NULL DEFAULT 0 COMMENT '支付状态（0=待支付, 1=支付成功, 2=支付失败, 3=已退款, 4=部分退款）',
  `pay_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '支付说明',
  `extra_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '扩展数据（JSON格式）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_payment_code`(`payment_code` ASC) USING BTREE,
  INDEX `idx_order`(`order_type` ASC, `order_code` ASC) USING BTREE,
  INDEX `idx_trade_no`(`trade_no` ASC) USING BTREE,
  INDEX `idx_pay_status`(`pay_status` ASC) USING BTREE,
  INDEX `idx_pay_time`(`pay_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '订单支付记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `finance_reconciliation`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `recon_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对账编码',
  `recon_type` tinyint NOT NULL COMMENT '对账类型（1=渠道对账, 2=供应商对账）',
  `target_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对账对象编码',
  `target_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对账对象名称',
  `period_start` date NOT NULL COMMENT '对账周期开始',
  `period_end` date NOT NULL COMMENT '对账周期结束',
  `our_order_count` int NOT NULL DEFAULT 0 COMMENT '我方订单数',
  `our_total_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '我方总金额',
  `their_order_count` int NULL DEFAULT NULL COMMENT '对方订单数',
  `their_total_amount` decimal(14, 2) NULL DEFAULT NULL COMMENT '对方总金额',
  `diff_count` int NOT NULL DEFAULT 0 COMMENT '差异订单数',
  `diff_amount` decimal(14, 2) NOT NULL DEFAULT 0.00 COMMENT '差异金额',
  `diff_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '差异明细（JSON格式）',
  `recon_result` tinyint NOT NULL DEFAULT 0 COMMENT '对账结果（0=有差异, 1=一致）',
  `handle_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '差异处理结果',
  `recon_time` datetime NOT NULL COMMENT '对账时间',
  `operator_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '操作人编码',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=对账中, 1=已完成, 2=待确认, 3=已确认）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_recon_code`(`recon_code` ASC) USING BTREE,
  INDEX `idx_target_code`(`target_code` ASC) USING BTREE,
  INDEX `idx_period`(`period_start` ASC, `period_end` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '对账记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `finance_refund`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `refund_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '退款编码',
  `order_type` tinyint NOT NULL COMMENT '订单类型',
  `order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单编号',
  `payment_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原支付记录编码',
  `refund_amount` decimal(14, 2) NOT NULL COMMENT '退款金额',
  `refund_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '退款原因',
  `refund_type` tinyint NOT NULL DEFAULT 1 COMMENT '退款类型（1=全额退款, 2=部分退款）',
  `refund_channel` tinyint NOT NULL DEFAULT 1 COMMENT '退款渠道（1=原路退回, 2=退到余额, 3=线下退款）',
  `refund_trade_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '退款交易号',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `refund_time` datetime NULL DEFAULT NULL COMMENT '退款完成时间',
  `auditor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核人编码',
  `auditor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核人姓名',
  `audit_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核备注',
  `refund_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0=待审核, 1=审核通过, 2=退款中, 3=退款成功, 4=审核拒绝, 5=退款失败）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_refund_code`(`refund_code` ASC) USING BTREE,
  INDEX `idx_order`(`order_type` ASC, `order_code` ASC) USING BTREE,
  INDEX `idx_refund_status`(`refund_status` ASC) USING BTREE,
  INDEX `idx_apply_time`(`apply_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '订单退款记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `goods_course`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码',
  `sku_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU编码',
  `sku_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU名称',
  `course_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程编码',
  `course_type` tinyint NOT NULL COMMENT '课程类型（1=线上课程, 2=线下课程, 3=直播课程）',
  `sku_price` decimal(12, 2) NOT NULL COMMENT 'SKU售价',
  `class_count` int NULL DEFAULT NULL COMMENT '课时数',
  `valid_days` int NULL DEFAULT NULL COMMENT '有效天数',
  `stock` int NOT NULL DEFAULT -1 COMMENT '库存',
  `sales_count` int NOT NULL DEFAULT 0 COMMENT '已售数量',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=停售, 1=在售）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sku_code`(`sku_code` ASC) USING BTREE,
  INDEX `idx_goods_code`(`goods_code` ASC) USING BTREE,
  INDEX `idx_course_code`(`course_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程商品SKU' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `goods_display_block`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码（关联goods_info.goods_code）',
  `block_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '板块类型（product_intro=产品介绍, rights_detail=权益详解, service_flow=服务流程, faq=常见问题, purchase_terms=购买须知, custom=自定义）',
  `block_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '板块标题（C端 tab 名，如\"权益详解\"）',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '富文本内容（HTML）',
  `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '图片key列表（JSON数组）',
  `image_descriptions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '图片描述列表（JSON数组，与images一一对应）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号（tab 顺序）',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=隐藏, 1=显示）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除（0=未删,1=已删）',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_goods_code`(`goods_code` ASC) USING BTREE,
  INDEX `idx_goods_type`(`goods_code` ASC, `block_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '商品展示内容板块（C/Agent端详情页 tab）' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `goods_equity`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码（1:1关联goods_info.goods_code）',
  `person_count` int NOT NULL DEFAULT 1 COMMENT '使用人人数（1=个人版,2=双人版,3+家庭版）',
  `validity_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '权益期限类型（1=固定天数（valid_days生效），2=终身）',
  `holder_rule` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '权益人构成规则JSON：{self:1,spouse:0|1,parent:0..4,designateAtActivation:bool}；person_count=1+spouse+parent',
  `share_mode` tinyint(1) NOT NULL DEFAULT 1 COMMENT '配额归属（0=按人独立配额，1=权益人共享池）',
  `valid_days` int NOT NULL DEFAULT 365 COMMENT '激活后有效天数',
  `shelf_life_days` int NOT NULL DEFAULT 730 COMMENT '库存有效期天数（未激活时）',
  `max_transferable` tinyint NOT NULL DEFAULT 0 COMMENT '可转让次数（0=不可转让，1/2/3=可转让N次）',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '权益配置说明',
  `sort_order` int NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '0=停用,1=启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system',
  `deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_goods_code`(`goods_code` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2086412931426713611 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '权益商品配置（商品类型特有配置，1:1关联goods_info）' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `goods_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码',
  `goods_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名称',
  `goods_short_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '商品简称',
  `goods_type` tinyint NOT NULL COMMENT '商品类型（1=养老权益, 2=场景营销, 3=培训课程, 4=旅游短居）',
  `category_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类编码',
  `brand_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '品牌名称',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '封面图URL',
  `display_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '页面展示配置JSON：{\"banners\":[\"key\"],\"thumbnail\":\"key\"}；thumbnail空=默认第一张/回退cover_image',
  `image_urls` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '商品图片（JSON数组）',
  `video_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '宣传视频URL',
  `goods_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '商品详细描述',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '商品摘要',
  `original_price` decimal(12, 2) NOT NULL COMMENT '原价',
  `sale_price` decimal(12, 2) NOT NULL COMMENT '售价',
  `cost_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '成本价',
  `price_unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '元' COMMENT '价格单位',
  `stock` int NOT NULL DEFAULT -1 COMMENT '库存（-1=不限）',
  `sales_count` int NOT NULL DEFAULT 0 COMMENT '已售数量',
  `view_count` int NOT NULL DEFAULT 0 COMMENT '浏览次数',
  `collect_count` int NOT NULL DEFAULT 0 COMMENT '收藏次数',
  `sale_start_time` datetime NULL DEFAULT NULL COMMENT '开售时间',
  `sale_end_time` datetime NULL DEFAULT NULL COMMENT '停售时间',
  `is_hot` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否热销（0=否, 1=是）',
  `is_new` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否新品（0=否, 1=是）',
  `is_recommend` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否推荐（0=否, 1=是）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `goods_status` tinyint NOT NULL DEFAULT 0 COMMENT '商品状态（0=草稿, 1=待上架, 2=已上架, 3=已下架, 4=已售罄）',
  `audit_status` tinyint NOT NULL DEFAULT 0 COMMENT '审核状态（0=待审核, 1=审核通过, 2=审核驳回）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_goods_code`(`goods_code` ASC) USING BTREE,
  INDEX `idx_goods_type`(`goods_type` ASC) USING BTREE,
  INDEX `idx_category_code`(`category_code` ASC) USING BTREE,
  INDEX `idx_goods_status`(`goods_status` ASC) USING BTREE,
  INDEX `idx_sort_order`(`sort_order` ASC) USING BTREE,
  INDEX `idx_sale_price`(`sale_price` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '商品信息' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `goods_scene`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码',
  `sku_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU编码',
  `sku_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU名称',
  `scene_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '场景编码',
  `park_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联机构编码',
  `sku_price` decimal(12, 2) NOT NULL COMMENT 'SKU售价',
  `person_limit` int NOT NULL DEFAULT 1 COMMENT '人数限制',
  `duration_hours` decimal(4, 1) NULL DEFAULT NULL COMMENT '活动时长（小时）',
  `schedule_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '排期说明',
  `stock` int NOT NULL DEFAULT -1 COMMENT '库存',
  `sales_count` int NOT NULL DEFAULT 0 COMMENT '已售数量',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=停售, 1=在售）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sku_code`(`sku_code` ASC) USING BTREE,
  INDEX `idx_goods_code`(`goods_code` ASC) USING BTREE,
  INDEX `idx_scene_code`(`scene_code` ASC) USING BTREE,
  INDEX `idx_park_code`(`park_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '场景商品SKU' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `goods_service_item_rel`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码（关联goods_equity.goods_code）',
  `item_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务项目编码（关联service_item.item_code）',
  `quantity` int NOT NULL DEFAULT 1,
  `quota_type` tinyint(1) NOT NULL DEFAULT 2 COMMENT '配额周期（1=终身总量,2=年度配额）',
  `network_scope` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '商品级服务网络收窄JSON：NULL=继承服务项目的网络范围；{\"mode\":\"custom\",\"parks\":[...]}=自选（结构同 service_item.service_network）',
  `admission_guaranteed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '保证入住权（0=无，1=有；长居/照护）',
  `admission_priority` tinyint(1) NOT NULL DEFAULT 0 COMMENT '优先入住权（0=无，1=有）',
  `admission_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '优惠入住权/旅居优惠权（0=无，1=有）',
  `discount_rate` decimal(4, 2) NULL DEFAULT NULL COMMENT '优惠折扣率（90.00=门市价9折；NULL=按协议未定，仅有优惠权标记）',
  `usage_rule` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '单次使用规则JSON（随心住类）：{maxDaysPerUse,maxNightsPerUse,maxRoomsPerUse,maxGuestsPerUse,requireBeneficiaryCheckIn,advanceBookDays,depositAmount,refundPolicy:[{beforeHours,refundRate}],blackoutType,blackoutDays}',
  `sort_order` int NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system',
  `deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_goods_item`(`goods_code` ASC, `item_code` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_goods_code`(`goods_code` ASC) USING BTREE,
  INDEX `idx_item_code`(`item_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2088550733744500738 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '商品-服务项目关联表（一个权益商品组合N个服务项目）' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `goods_sojourn`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码',
  `sku_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU编码',
  `sku_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU名称',
  `park_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '机构编码',
  `room_type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联房间类型编码',
  `room_type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房间类型名称',
  `care_type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联照护类型编码',
  `food_type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联餐饮类型编码',
  `sku_price` decimal(12, 2) NOT NULL COMMENT 'SKU售价',
  `price_unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '元/月' COMMENT '价格单位',
  `min_days` int NOT NULL DEFAULT 30 COMMENT '最少天数',
  `max_days` int NULL DEFAULT NULL COMMENT '最多天数（NULL=不限）',
  `stock` int NOT NULL DEFAULT -1 COMMENT '库存',
  `sales_count` int NOT NULL DEFAULT 0 COMMENT '已售数量',
  `effective_date` date NOT NULL COMMENT '生效日期',
  `expire_date` date NULL DEFAULT NULL COMMENT '失效日期',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（0=停售, 1=在售）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sku_code`(`sku_code` ASC) USING BTREE,
  INDEX `idx_goods_code`(`goods_code` ASC) USING BTREE,
  INDEX `idx_park_code`(`park_code` ASC) USING BTREE,
  INDEX `idx_room_type_code`(`room_type_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '旅居房间商品SKU' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `lead_content_read_record`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `lead_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索编码（lead_info.lead_code）',
  `visitor_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '访客令牌（冗余，便于直查）',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码（分享人所属渠道）',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分享人代理人编码（NULL=直接访问）',
  `content_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容编码',
  `content_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '内容标题（冗余快照）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '阅读时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_lead_code`(`lead_code` ASC) USING BTREE,
  INDEX `idx_visitor_token`(`visitor_token` ASC) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_content_code`(`content_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '内容阅读线索记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `lead_info`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `lead_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索编码（VL+日期+序号，全平台唯一）',
  `visitor_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '访客令牌（匿名唯一标识，UUID）',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属渠道编码（首触渠道）',
  `openid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信OpenID（授权后回填）',
  `union_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信UnionID（授权后回填）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '手机号（留资后回填）',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '姓名/称呼（留资后回填）',
  `wx_nickname` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信昵称',
  `wx_avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信头像URL',
  `visitor_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '访客环境来源（wechat/browser/unknown）',
  `source_type` tinyint NOT NULL DEFAULT 4 COMMENT '来源类型（1=内容分享, 2=工具分享, 3=海报分享, 4=直接访问）',
  `source_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源编码（首个触点的 bizCode）',
  `client_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联客户编码（留资/注册后回填 client_info.client_code）',
  `last_interact_time` datetime NULL DEFAULT NULL COMMENT '最后互动时间',
  `last_interact_type` tinyint NULL DEFAULT NULL COMMENT '最后互动类型（1=内容 2=工具 3=海报）',
  `interact_count` int NOT NULL DEFAULT 0 COMMENT '互动总次数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_visitor_token`(`visitor_token` ASC) USING BTREE,
  UNIQUE INDEX `uk_lead_code`(`lead_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_client_code`(`client_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '访客线索' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `lead_poster_view_record`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `lead_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索编码（lead_info.lead_code）',
  `visitor_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '访客令牌（冗余，便于直查）',
  `channel_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道编码（分享人所属渠道）',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分享人代理人编码（NULL=直接访问）',
  `template_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '海报模板编码',
  `poster_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '海报标题（冗余快照）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '浏览时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_lead_code`(`lead_code` ASC) USING BTREE,
  INDEX `idx_visitor_token`(`visitor_token` ASC) USING BTREE,
  INDEX `idx_agent_code`(`agent_code` ASC) USING BTREE,
  INDEX `idx_template_code`(`template_code` ASC) USING BTREE,
  INDEX `idx_channel_code`(`channel_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '海报浏览线索记录' ROW_FORMAT = Dynamic;



CREATE TABLE IF NOT EXISTS `lead_tool_use_record`  (
